import{_ as l,C as s,o as e,c as d,j as i,a as r,E as o,a3 as n}from"./chunks/framework.C6R8kWFE.js";const T=JSON.parse(`{"title":"15-dars (Mentor). UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli","description":"","frontmatter":{"title":"15-dars (Mentor). UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":5,"link":"/mentor/9-sinf/hafta-05/"},"g":15,"title":"UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli","lead":"Nazariya tugadi — endi qo'l ishi! Bugun Figma'da haqiqiy elektron kutubxona sahifasining eng muhim ikki qismini yasaysiz: qidiruvli header va kategoriyalar paneli. Har bir piksel, rang va burchak aniq qiymat bilan beriladi.","slide":"/slaydlar/9-sinf/hafta-05/dars-3.html","test":"/slaydlar/9-sinf/hafta-05/dars-3-test.html","student_link":"/9-sinf/hafta-05/dars-3","tabs":[{"g":13,"link":"/mentor/9-sinf/hafta-05/dars-1","current":false},{"g":14,"link":"/mentor/9-sinf/hafta-05/dars-2","current":false},{"g":15,"link":"/mentor/9-sinf/hafta-05/dars-3","current":true}],"prev":{"g":14,"title":"Mashhur UI kitlar: HIG, Ant Design, Bootstrap, Figma UI Kit, Material UI","link":"/mentor/9-sinf/hafta-05/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf/hafta-05/dars-3.md","filePath":"mentor/9-sinf/hafta-05/dars-3.md"}`),h={name:"mentor/9-sinf/hafta-05/dars-3.md"},g={class:"blk"},u={id:"_1-dars-rejasi",tabindex:"-1"},m={class:"blk"},k={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},p={id:"_3-amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},b={id:"_4-tezkor-nazorat-savollar-va-javoblar",tabindex:"-1"},q={class:"blk"},f={id:"_5-uyga-vazifa",tabindex:"-1"};function c(_,a,x,F,z,I){const t=s("Icon");return e(),d("div",null,[a[15]||(a[15]=i("p",null,[i("strong",null,"Hafta:"),r(" 5 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" dizayn amaliyoti (Figma) · "),i("strong",null,"I-bob"),r(", 1.5-mavzu, 3-dars")],-1)),a[16]||(a[16]=i("p",null,[i("strong",null,"Manba:"),r(" uslubiy ko'rsatma, 1.4 «UI kit va dizayn tizimlariga kirish» — amaliy qism (1.29–1.42-rasmlar: header'da qidiruv maydoni Rectangle, W/H va x/y, Fill #FFFFFF, Corner radius 25; 50 × 50 qidiruv tugmasi, sariq #FFFB00, opacity ≈ 47%, radius 25; Fill → Image orqali lupa ikonka va Crop; «Kirish» matni Inter 25 px; profil ikonka 38 × 38, Exposure; savat ikonka; Shape tools → Line, stroke #000000, 2 px, center; yon panel Rectangle — Drop shadow, Opacity 100%, Fill #FFFFFF, Stroke #000000 1 px Inside; kategoriya ajratuvchi chiziqlari; red guides orqali masofalarni tekshirish; «more categories» havolasi; kategoriya nomlari, masalan «Maktab darsliklari»; amaliy topshiriq: sahifaga tugmalar va qo'shimcha elementlar joylashtirib, yagona uslubni ta'minlash). Komponentga aylantirish (Create component) — 13-darsdagi atom/molekula g'oyasini mustahkamlash uchun qo'shimcha.")],-1)),i("div",g,[i("h2",u,[o(t,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchilar 13–14-darslarda o&#39;rganilgan UI kit g&#39;oyasini amalda qo&#39;llab, Figma&#39;da «E-kutubxona» sahifasining header qismini (qidiruv maydoni, qidiruv tugmasi, «Kirish», profil va savat ikonkalari) va yon tomondagi «Kategoriya» panelini aniq o&#39;lcham, rang, radius, stroke va soya parametrlari bilan yaratadi; elementlarni yagona uslubga keltiradi va qayta ishlatiladigan komponentga aylantiradi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Rectangle o&#39;lchami (W/H), joylashuvi (x/y), Fill va Corner radius&#39;ini Design panelida aniq sozlaydi;</li><li>Fill → Image orqali ikonka yuklaydi va Crop bilan moslaydi; Exposure bilan ikonka ko&#39;rinishini fonga moslaydi;</li><li>Line elementiga stroke (rang, qalinlik, joylashuv) beradi va bo&#39;limlarni ajratadi;</li><li>Drop shadow va Inside stroke bilan yon panel yaratadi, red guides bilan masofalarni tekshiradi;</li><li>Header va kategoriya panelini yagona uslubda yig&#39;ib, qidiruv maydonini komponentga aylantiradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>Mashhur UI kitlar, atom → molekula → organizm. Namuna: tayyor «E-kutubxona» header&#39;i</td></tr><tr><td>10–20 daq</td><td>Ko&#39;rsatish</td><td>Design paneli: W/H, x/y, Fill, Corner radius, Effects, Stroke</td></tr><tr><td>20–35 daq</td><td>Amaliyot 1</td><td>Header: qidiruv maydoni, sariq qidiruv tugmasi, lupa ikonka, «Kirish», profil va savat</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–68 daq</td><td>Amaliyot 2</td><td>Kategoriya paneli: soya, stroke, ajratuvchi chiziqlar, nomlar, «more categories», red guides</td></tr><tr><td>68–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol, juftlikda bir-birining ishini tekshirish</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Keyingi hafta: Figma&#39;da komponentlar va prototiplash</td></tr></tbody></table><hr>',5))]),i("div",m,[i("h2",k,[o(t,{name:"file-text"}),a[3]||(a[3]=r(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_2-1-sahifa-tuzilmasi" tabindex="-1">2.1. Sahifa tuzilmasi <a class="header-anchor" href="#_2-1-sahifa-tuzilmasi" aria-label="Permalink to &quot;2.1. Sahifa tuzilmasi&quot;">​</a></h3><p>«E-kutubxona» bosh sahifasi uchun Desktop frame (1440 × 1024) olinadi. Bugun 2 ta organizm yig&#39;iladi:</p><ul><li><strong>Header</strong> — yuqori panel: logotip, markazda qidiruv maydoni + qidiruv tugmasi, o&#39;ngda «Kirish», profil va savat ikonkalari.</li><li><strong>Kategoriya paneli</strong> — chap tomonda: sarlavha, kategoriyalar ro&#39;yxati, ajratuvchi chiziqlar, «more categories» havolasi.</li></ul><h3 id="_2-2-qidiruv-maydoni-1-29–1-30-rasmlar" tabindex="-1">2.2. Qidiruv maydoni (1.29–1.30-rasmlar) <a class="header-anchor" href="#_2-2-qidiruv-maydoni-1-29–1-30-rasmlar" aria-label="Permalink to &quot;2.2. Qidiruv maydoni (1.29–1.30-rasmlar)&quot;">​</a></h3><ol><li><strong>Rectangle (R)</strong> bilan header markazida to&#39;rtburchak chiziladi.</li><li>Design panelida <strong>W</strong> (eni) va <strong>H</strong> (bo&#39;yi), <strong>X</strong> va <strong>Y</strong> koordinatalari aniq kiritiladi (masalan, W 600, H 50).</li><li><strong>Fill</strong> → rang oynasi → <strong>#FFFFFF</strong> (oq) — toza va neytral ko&#39;rinish.</li><li><strong>Corner radius = 25</strong> — balandlikning yarmi, shuning uchun maydon to&#39;liq yumaloq («pill») bo&#39;ladi.</li></ol><h3 id="_2-3-qidiruv-tugmasi-va-ikonka-1-31–1-33-rasmlar" tabindex="-1">2.3. Qidiruv tugmasi va ikonka (1.31–1.33-rasmlar) <a class="header-anchor" href="#_2-3-qidiruv-tugmasi-va-ikonka-1-31–1-33-rasmlar" aria-label="Permalink to &quot;2.3. Qidiruv tugmasi va ikonka (1.31–1.33-rasmlar)&quot;">​</a></h3><ol><li>Maydonning o&#39;ng tomoniga <strong>50 × 50</strong> Rectangle.</li><li>Fill: sariq <strong>#FFFB00</strong>, <strong>opacity ≈ 47%</strong>; <strong>Corner radius = 25</strong> — dumaloq tugma.</li><li>Lupa ikonka: yangi kichik Rectangle → <strong>Fill → Image</strong> → kompyuterdan rasm → <strong>Crop</strong> bilan o&#39;lcham va joylashuvni moslash.</li></ol><h3 id="_2-4-«kirish»-profil-va-savat-1-34–1-36-rasmlar" tabindex="-1">2.4. «Kirish», profil va savat (1.34–1.36-rasmlar) <a class="header-anchor" href="#_2-4-«kirish»-profil-va-savat-1-34–1-36-rasmlar" aria-label="Permalink to &quot;2.4. «Kirish», profil va savat (1.34–1.36-rasmlar)&quot;">​</a></h3><ul><li><strong>Text (T)</strong> → «Kirish»: shrift <strong>Inter</strong>, o&#39;lcham <strong>25 px</strong> — tizimga kirish funksiyasi.</li><li>Profil ikonka: Image sifatida yuklanadi, o&#39;lchami <strong>38 × 38 px</strong>; Image sozlamalarida <strong>Exposure</strong> (yorug&#39;lik) bilan fonga moslanadi.</li><li>Savat (cart) ikonka ham xuddi shunday: Image + Exposure.</li></ul><h3 id="_2-5-chiziq-bilan-ajratish-1-37–1-38-rasmlar" tabindex="-1">2.5. Chiziq bilan ajratish (1.37–1.38-rasmlar) <a class="header-anchor" href="#_2-5-chiziq-bilan-ajratish-1-37–1-38-rasmlar" aria-label="Permalink to &quot;2.5. Chiziq bilan ajratish (1.37–1.38-rasmlar)&quot;">​</a></h3><ul><li>Pastki asboblar panelidagi <strong>Shape tools</strong>: Rectangle, Line, Arrow, Ellipse, Polygon, Star → <strong>Line (L)</strong>.</li><li><strong>Stroke:</strong> rang <strong>#000000</strong>, qalinlik <strong>2 px</strong>, joylashuv <strong>Center</strong> — header va kontentni ajratadi.</li></ul><h3 id="_2-6-kategoriya-paneli-1-39–1-42-rasmlar" tabindex="-1">2.6. Kategoriya paneli (1.39–1.42-rasmlar) <a class="header-anchor" href="#_2-6-kategoriya-paneli-1-39–1-42-rasmlar" aria-label="Permalink to &quot;2.6. Kategoriya paneli (1.39–1.42-rasmlar)&quot;">​</a></h3><ol><li>Chap tomonda vertikal Rectangle: <strong>Opacity 100%</strong>, <strong>Fill #FFFFFF</strong>, <strong>Stroke #000000, 1 px, Inside</strong>.</li><li><strong>Effects → Drop shadow</strong> — panel fondan ajralib, chuqurlik (depth) hissi paydo bo&#39;ladi.</li><li>Ichida bir nechta gorizontal <strong>Line</strong> — har bir kategoriya bandini ajratadi.</li><li><strong>Red guides:</strong> element tanlangan holda <strong>Alt (Option)</strong> bosib turib boshqa elementga sichqonchani olib borilsa, qizil o&#39;lchov chiziqlari masofani ko&#39;rsatadi — oraliqlar teng ekanini tekshiring (8-point grid: 16 yoki 24).</li><li>Pastda <strong>«more categories»</strong> matni — qo&#39;shimcha kategoriyalar sahifasiga havola.</li><li>Kategoriya nomlari: «Maktab darsliklari», «Badiiy adabiyot», «Ilmiy-ommabop», «Bolalar adabiyoti», «Chet tillar».</li></ol><h3 id="_2-7-stroke-joylashuvi" tabindex="-1">2.7. Stroke joylashuvi <a class="header-anchor" href="#_2-7-stroke-joylashuvi" aria-label="Permalink to &quot;2.7. Stroke joylashuvi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Joylashuv</th><th>Natija</th></tr></thead><tbody><tr><td><strong>Inside</strong></td><td>chiziq shakl ichida — o&#39;lcham o&#39;zgarmaydi (panel uchun qulay)</td></tr><tr><td><strong>Center</strong></td><td>yarmi ichda, yarmi tashqarida</td></tr><tr><td><strong>Outside</strong></td><td>chiziq tashqarida — element vizual kattalashadi</td></tr></tbody></table><h3 id="_2-8-yagona-uslub-va-komponent" tabindex="-1">2.8. Yagona uslub va komponent <a class="header-anchor" href="#_2-8-yagona-uslub-va-komponent" aria-label="Permalink to &quot;2.8. Yagona uslub va komponent&quot;">​</a></h3><ul><li>Hamma joyda 13-darsdagi <strong>Color va Text styles</strong> ishlatiladi (oq fon, sariq urg&#39;u, qora chiziq, Inter).</li><li>Qidiruv maydoni + tugma + lupa tanlanadi → <strong>Ctrl/Cmd + Alt/Option + K</strong> (Create component) → nom <code>Search/Default</code>. Endi uni boshqa sahifalarda nusxa (instance) sifatida ishlatish mumkin — bu UI kitning birinchi «molekulasi».</li></ul><hr>',18))]),i("div",y,[i("h2",p,[o(t,{name:"file-text"}),a[6]||(a[6]=r(" 3. Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-topshiriq-qidiruv-maydoni-oson" tabindex="-1">1-topshiriq. Qidiruv maydoni (oson) <a class="header-anchor" href="#_1-topshiriq-qidiruv-maydoni-oson" aria-label="Permalink to &quot;1-topshiriq. Qidiruv maydoni (oson)&quot;">​</a></h3><p>600 × 50 oq Rectangle yarating, Corner radius 25 bering, o&#39;ng tomoniga 50 × 50 sariq (#FFFB00, 47%) dumaloq tugma joylashtiring.</p><p><strong>Yechim (tekshiruv):</strong> Design panelida W 600 / H 50, radius 25; tugma 50 × 50, Fill #FFFB00 47%, radius 25; tugma maydonning o&#39;ng chetiga tekislangan (Align right).</p><h3 id="_2-topshiriq-to-liq-header-o-rta" tabindex="-1">2-topshiriq. To&#39;liq header (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-to-liq-header-o-rta" aria-label="Permalink to &quot;2-topshiriq. To&#39;liq header (o&#39;rta)&quot;">​</a></h3><p>Header&#39;ga lupa ikonka (Fill → Image + Crop), «Kirish» (Inter 25 px), profil (38 × 38) va savat ikonkalarini qo&#39;shing, pastdan 2 px qora Line bilan ajrating.</p><p><strong>Yechim (tekshiruv):</strong> ikonkalar bir xil balandlikda va vertikal markazda; «Kirish» va ikonkalar orasidagi masofa red guides bo&#39;yicha teng; Line stroke #000000 2 px Center; Exposure bilan ikonkalar fonda «yorqin dog&#39;» bo&#39;lib qolmagan.</p><h3 id="_3-topshiriq-kategoriya-paneli-va-komponent-qiyin" tabindex="-1">3-topshiriq. Kategoriya paneli va komponent (qiyin) <a class="header-anchor" href="#_3-topshiriq-kategoriya-paneli-va-komponent-qiyin" aria-label="Permalink to &quot;3-topshiriq. Kategoriya paneli va komponent (qiyin)&quot;">​</a></h3><p>Yon panelni (Fill #FFFFFF, Stroke #000000 1 px Inside, Drop shadow) yarating, 5 ta kategoriya va ajratuvchi chiziqlar, «more categories» havolasini qo&#39;shing. Qidiruv blokini <code>Search/Default</code> komponentiga aylantiring va sahifaga yana 1 ta tugma (masalan, «Barcha kitoblar») yagona uslubda qo&#39;shing.</p><p><strong>Yechim (tekshiruv):</strong> Layers panelida panel guruh (Frame) nomi <code>Kategoriya</code>; 5 nom alohida qatorlarda, chiziqlar orasidagi masofa teng; Effects&#39;da Drop shadow; Assets bo&#39;limida <code>Search/Default</code> komponenti bor; yangi tugma ranglari va radiusi qidiruv tugmasi bilan uyg&#39;un.</p><hr>',10))]),i("div",v,[i("h2",b,[o(t,{name:"file-text"}),a[9]||(a[9]=r(" 4. Tezkor nazorat (savollar va javoblar) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollar-va-javoblar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat (savollar va javoblar)"'},"​",-1))]),a[11]||(a[11]=n("<ol><li><strong>Qidiruv maydoni nega Corner radius 25 bilan to&#39;liq yumaloq bo&#39;ladi?</strong><ul><li><em>Javob:</em> Balandligi 50 px, radius uning yarmi — burchaklar to&#39;liq yarim doira bo&#39;ladi.</li></ul></li><li><strong>Rectangle ichiga rasm (ikonka) qanday joylanadi?</strong><ul><li><em>Javob:</em> Fill → Image → rasmni yuklash → Crop bilan moslash.</li></ul></li><li><strong>Exposure nima uchun ishlatildi?</strong><ul><li><em>Javob:</em> Ikonka yorug&#39;ligini sozlab, uni header foniga uyg&#39;unlashtirish uchun.</li></ul></li><li><strong>Stroke Inside va Outside farqi?</strong><ul><li><em>Javob:</em> Inside — chiziq shakl ichida, o&#39;lcham o&#39;zgarmaydi; Outside — tashqarida, element vizual kattalashadi.</li></ul></li><li><strong>Red guides nima uchun kerak?</strong><ul><li><em>Javob:</em> Elementlar orasidagi masofani o&#39;lchab, tartibli va simmetrik joylashuvni tekshirish uchun.</li></ul></li></ol><hr>",2))]),i("div",q,[i("h2",f,[o(t,{name:"file-text"}),a[12]||(a[12]=r(" 5. Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 5. Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"«E-kutubxona» sahifasiga (header + kategoriya paneli) yana 3 ta element qo'shing: asosiy menyu (Bosh sahifa, Yangi kitoblar, Mualliflar, Aloqa), «Barcha kitoblar» tugmasi va banner joyi."),i("li",null,"Barcha elementlar yagona uslubda bo'lsin: bir xil ranglar (stillar), Inter shrifti, radius va 8-point grid oraliqlari."),i("li",null,"Qidiruv blokini va tugmani komponentga aylantiring; Figma havolasini (view huquqi bilan) mentorga yuboring.")],-1))])])}const C=l(h,[["render",c]]);export{T as __pageData,C as default};
